CREATE TABLE `mes_task` (
  `id` bigint NOT NULL COMMENT 'id',
  `sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流转批次号',
  `pro_id` bigint DEFAULT NULL COMMENT '产品',
  `workplace_id` bigint DEFAULT NULL COMMENT '工作站',
  `user_id` bigint DEFAULT NULL COMMENT '用户',
  `needcount` int DEFAULT NULL COMMENT '所需数量',
  `original_needcount` bigint DEFAULT NULL COMMENT '原始需求数量（记录主任务被拆分前的总数量）',
  `markcount` int DEFAULT NULL COMMENT '生产数量',
  `okprocess` int DEFAULT '0' COMMENT '完成工序',
  `scrapcount` int DEFAULT NULL COMMENT '报废数量',
  `is_check` int DEFAULT '0' COMMENT '全部质检次数',
  `currproid` bigint DEFAULT NULL COMMENT '流程id',
  `currprocess` int DEFAULT NULL COMMENT '当前流程',
  `allprocess` int DEFAULT NULL COMMENT '所有工序',
  `redoingcount` int DEFAULT NULL COMMENT '返工数量',
  `redoingid` bigint DEFAULT NULL COMMENT '返工id',
  `is_top` tinyint DEFAULT NULL COMMENT '是否加急',
  `work_id` bigint DEFAULT NULL COMMENT '主表id',
  `process_route_id` bigint DEFAULT NULL COMMENT '关联的工艺路线ID（process_route.id）',
  `step_id` bigint DEFAULT NULL COMMENT '关联的工序步骤ID（process_step.id）',
  `branch_id` bigint DEFAULT NULL COMMENT '分支主任务ID（NULL=主任务，有值=分支任务）',
  `branch_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '分支状态：0=主任务，1=分支任务（部分出库）',
  `bom_item_id` bigint DEFAULT NULL COMMENT '关联的BOM组件ID（BOM模式使用，mes_bom_item.id）',
  `type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '类型',
  `sort` int DEFAULT NULL COMMENT '排序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '角色状态（1正常 2进行中 3已完成 0异常完工,4待检查8其他用户完成）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '000000' COMMENT '租户编号',
  `mustbe` int DEFAULT NULL COMMENT '是否关键工序',
  `enough` int DEFAULT '1' COMMENT '是否够量',
  `stocknum` int DEFAULT '0' COMMENT '需出库数量',
  `outstocknum` int DEFAULT '0' COMMENT '出库数量',
  `checknum` int DEFAULT '0' COMMENT '当前质检次数',
  `ischecknew` int DEFAULT '0' COMMENT '是否通过质检',
  `worktype` int DEFAULT '0' COMMENT '流转类型',
  `remark2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `procure` int DEFAULT '0' COMMENT '是否采购完成',
  `resu` int DEFAULT '0' COMMENT '结果确认',
  `workplace_dispatch` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'dispatch source RULE/MANUAL/FALLBACK',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_step_id` (`step_id`) USING BTREE,
  KEY `idx_process_route_id` (`process_route_id`) USING BTREE,
  KEY `idx_bom_item` (`bom_item_id`) USING BTREE,
  KEY `idx_branch_id` (`branch_id`) USING BTREE COMMENT '分支任务查询索引',
  KEY `idx_branch_status` (`branch_status`) USING BTREE COMMENT '分支状态查询索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
